 (100, 'Dell XPS 15 OLED Pro', 'dell-xps-15-oled-pro', 'Dell XPS 15 OLED Pro - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về Dell XPS 15 OLED Pro: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Dell', 54000000, 'https://images.unsplash.com/photo-1593642632823-8f785ba67e45?q=80&w=400', 15, 5),
 (101, 'HP Spectre x360 Gold Pro', 'hp-spectre-x360-gold-pro', 'HP Spectre x360 Gold Pro - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về HP Spectre x360 Gold Pro: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'HP', 50400000, 'https://images.unsplash.com/photo-1525547719571-a2d4ac8945e2?q=80&w=400', 16, 5),
 (102, 'Asus Zenbook 14 Space Pro', 'asus-zenbook-14-space-pro', 'Asus Zenbook 14 Space Pro - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về Asus Zenbook 14 Space Pro: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Asus', 33600000, 'https://images.unsplash.com/photo-1531297484001-80022131f5a1?q=80&w=400', 17, 5),
 (103, 'Lenovo ThinkPad X1 Carbon Pro', 'lenovo-thinkpad-x1-carbon-pro', 'Lenovo ThinkPad X1 Carbon Pro - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về Lenovo ThinkPad X1 Carbon Pro: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Lenovo', 57600000, 'https://images.unsplash.com/photo-1618424181497-157f25b6ddd5?q=80&w=400', 18, 5),
 (104, 'Acer Swift Edge Lightweight Pro', 'acer-swift-edge-lightweight-pro', 'Acer Swift Edge Lightweight Pro - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về Acer Swift Edge Lightweight Pro: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Acer', 28800000, 'https://images.unsplash.com/photo-1541807084-5c52b6b3adef?q=80&w=400', 19, 5),
 (105, 'Razer Blade 16 Gaming Pro', 'razer-blade-16-gaming-pro', 'Razer Blade 16 Gaming Pro - sản phẩm chính hãng hàng đầu, bảo hành 12 tháng, ưu đãi đặc quyền.', 'Chi tiết về Razer Blade 16 Gaming Pro: Sản phẩm sở hữu thiết kế đột phá, cấu hình đỉnh cao và chất lượng vượt trội. Thích hợp sử dụng học tập, làm việc, thể thao hay thời trang hàng ngày. Đầy đủ phụ kiện chính hãng đi kèm trong hộp.', 'Razer', 102000000, 'https://images.unsplash.com/photo-1603302576837-37561b2e2302?q=80&w=400', 20, 5)
